import { debounce } from 'lodash'
import { useCallback, useEffect, useState } from 'react'
import { useHistory, useParams } from 'react-router'
import { Container } from '../../../../../../components'
import WorkshopList from '../../../components/WorkshopList'
import WorkshopDetail from '../../../components/WorkshopDetail'
import ProviderWorkshopStyles from '../../ProviderList/container/index.style'
import { ProviderWorkshopsStyleWrapper } from './index.style'
import { useApiContextValue, useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { useGlobalContextValue } from '../../../../../../contextProvider/GlobalContext'

const ProviderWorkshops = () => {
  const [searchText, setSearchText] = useState()
  const [{ showSnackbar }] = useGlobalContextValue()
  const params = useParams()
  const history = useHistory()
  const [{ workshopListData }] = useApiContextValue()
  const { state } = history.location
  const [{ WORKSHOP_LIST_LOADER }] = useLoaderContextValue()
  const [{ WORKSHOP_LIST_ERROR, workshopListStatus }] = useErrorContextValue()
  const { resetError } = useResetError()
  const handleSelect = useCallback((data) => {
    history.push({ state: { ...state, data, showWorkshopDetail: true } })
  }, [history, state])

  const showLoader = WORKSHOP_LIST_LOADER && !workshopListData?.data?.length

  useEffect(() => {
    if (WORKSHOP_LIST_ERROR) {
      showSnackbar.error({ text: workshopListStatus, visible: true })
    }
    return () => { resetError(['WORKSHOP_LIST_ERROR', 'workshopListStatus']) }
  }, [WORKSHOP_LIST_ERROR, workshopListStatus, showSnackbar, resetError])

  return (
    <Container
      className='bg-white'
      loader={!!showLoader}
      title={state.providerName}
      onSearch={debounce(setSearchText, 500)}
      showSearchBar
    >
      <ProviderWorkshopsStyleWrapper>
        <ProviderWorkshopStyles />
        {
          state.showWorkshopDetail
            ? <WorkshopDetail />
            : (
              <WorkshopList
                searchText={searchText}
                onSelect={handleSelect}
                code={params.providerCode}
              />
            )
        }
      </ProviderWorkshopsStyleWrapper>
    </Container>
  )
}
export default ProviderWorkshops
