import { useGet, useResetState } from '@pasarpolis/common-react-hooks'
import { useCallback, useEffect, useState } from 'react'
import LazyLoader from '../../../../../components/LazyLoader'
import Switch from '../../../../../components/Switch'
import WorkshopCard from '../WorkshopCard'
import { workshopListApi } from './constants'
import { WorkshopListStyleWrapper } from './index.style'

const WorkshopList = ({ searchText = '', code, onSelect }) => {
  const [workshopListData, providerWorkshopListRequest] = useGet(workshopListApi(code))
  const { resetState } = useResetState()
  const [showOnlyOfficials, setShowOnlyOfficials] = useState(false)

  const callProviderWorkshopListRequest = useCallback(() => {
    providerWorkshopListRequest({
      provider_code: code,
      page: 1,
      product_code: 'car-protection',
      is_authorized: showOnlyOfficials,
      q: searchText
    })
    resetState(['workshopListData'])
  }, [providerWorkshopListRequest, code, searchText, showOnlyOfficials, resetState])

  const handleShowOnlyOfficialsChange = useCallback((e) => {
    setShowOnlyOfficials(e.target.checked)
  }, [])

  useEffect(() => {
    callProviderWorkshopListRequest()
  }, [callProviderWorkshopListRequest])

  return (
    <WorkshopListStyleWrapper>
      <div className='p-16 bg-gray flex-container text-block'>
        <div className='text-dark text-small flex-grow-1 flex-container align-center'>
          Tampilkan bengkel resmi saja.
        </div>
        <div>
          <Switch id='adfs' checked={showOnlyOfficials} onChange={handleShowOnlyOfficialsChange} />
        </div>
      </div>
      <div className='p-16 bg-gray text-dark text-small text-bold'>
        {workshopListData?.total_workshops} bengkel ditemukan.
      </div>
      <div>
        {
          workshopListData?.data?.map((workshop, index) => (
            <WorkshopCard onSelect={onSelect} key={index} data={workshop} />
          ))
        }
        <LazyLoader
          requestParams={{
            is_authorized: showOnlyOfficials,
            q: searchText,
            product_code: 'car-protection',
            provider_code: code
          }}
          metaData={{
            total_pages: workshopListData?.total_pages,
            page: Number(workshopListData?.current_page)
          }}
          responseData={workshopListData}
          request={providerWorkshopListRequest}
          pageSize={10}
        />
      </div>
    </WorkshopListStyleWrapper>
  )
}
export default WorkshopList
