export const reducer = (state, action) => {
  const { payload } = action
  switch (action.type) {
    case 'WORKSHOP_LIST':
      return {
        ...state,
        workshopListData: {
          ...payload.workshopListData,
          total_pages: payload?.workshopListData?.total_pages || state?.workshopListData?.total_pages,
          current_page: payload?.workshopListData?.current_page || state?.workshopListData?.current_page,
          data: [
            ...(state.workshopListData?.data || []),
            ...(payload?.workshopListData?.data || [])
          ]
        }
      }
    default:
      return state
  }
}
