import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { ICON_SHIELD_FILLED, INSURANCE_PROVIDER } from '../../../../../images'
import { WorkshopCardStyleWrapper } from './index.style'

const WorkshopCard = ({ data, onSelect, showTotalInsurance = true, noHorizontalPadding = false }) => {
  const { name, address, brand } = data || {}
  return (
    <WorkshopCardStyleWrapper onClick={() => onSelect(data)} noHorizontalPadding={noHorizontalPadding}>
      <div className='flex-container'>
        <div className='flex-grow-1'>
          {
            brand && (
              <div className='brand text-dark-gray'>
                {brand}
              </div>
            )
          }
          <div className='text-bold text-normal autoshop-name-container'>
            {name}
          </div>
        </div>
        {
          data.is_authorized && (
            <div className='flex-container align-center'>
              <img
                className='status-icon'
                src={ICON_SHIELD_FILLED}
                alt='Workshop Status'
              />
            </div>
          )
        }
      </div>
      <div className='text-small'>
        {address}
      </div>
      {
        showTotalInsurance && data.num_providers && (
          <div className='flex-container provider-insurance-container'>
            <div className='flex-container align-center'>
              <img
                className='provider-icon'
                alt='Parent Icon'
                src={INSURANCE_PROVIDER}
              />
            </div>
            <CustomText
              size='0.75em'
              color={AgentColorPallette.fontGrey}
              weight={700}
              padLeft='1rem'
            >
              {data.num_providers + ' provider asuransi'}
            </CustomText>
          </div>
        )
      }
    </WorkshopCardStyleWrapper>
  )
}
export default WorkshopCard
