import { useCallback, useEffect, useRef } from 'react'

/**
 * Automatically loads more data when end of page is reached
 *
 * @param {object} props
 * @param {() => void} props.onPageEnd
 * @return {{ loadMoreRef: React.MutableRefObject<HTMLElement> }}
 */
function useLoadMoreData ({ onPageEnd }) {
  const prev = useRef({})
  const observer = useRef()
  const loadMoreRef = useRef(null)

  const handleObserver = useCallback((entities) => {
    const entity = entities[0]
    const y = entity.boundingClientRect.y
    const screenInnerHeight = window.screen.height
    // if prevY is greater than and current y is less than from the screenHeight
    // only then allowed else not allowed the next call
    // need to check the intersecting point also
    if (
      ((prev.current.prevY > screenInnerHeight) && (y < screenInnerHeight)) &&
      (prev.current.prevY > y) && entity.isIntersecting
    ) {
      onPageEnd()
    }
    prev.current.prevY = y
  }, [onPageEnd])

  useEffect(() => {
    // On first render, init Intersection Observer
    observer.current = new IntersectionObserver(
      handleObserver,
      {
        root: null,
        rootMargin: '0px',
        threshold: 1.0
      }
    )
    if (loadMoreRef.current) {
      // Assign loadMoreRef to be observed by observer
      observer.current.observe(loadMoreRef.current)
    }

    // Remove observer on unmount
    return () => {
      observer.current.disconnect()
    }
  }, [handleObserver])

  return { loadMoreRef }
}

export default useLoadMoreData
